const cfg = $('00 Einstellungen').first().json;
const raw = String(cfg.chatInput || '').trim().replace(/[−–—]/g, '-');

const HILFE = 'Befehle in dieser Version:\n/neu +18 <Thema>   oder   /neu -18 <Thema>   (Altersstufe ist Pflicht)\nOptional: alter:6-9   typ:sachbuch|anleitung|geschichtsbuch|dokumentation|malbuch|raetsel|kinderbuch|roman|comic\nBeispiel: /neu +18 Selbstverteidigung für Frauen';

// Muss mit bibliothek/buchart.yaml übereinstimmen
const PROFILE = {
  sachbuch:       { seiten: '40-70', mitte: 55,  faktenmodus: 'streng', bilder: 'nur wo sie erklären' },
  anleitung:      { seiten: '40-70', mitte: 55,  faktenmodus: 'streng', bilder: 'viele; Pläne mit Maßen aus Code' },
  geschichtsbuch: { seiten: '300-400 und mehr', mitte: 350, faktenmodus: 'streng', bilder: 'echte Fotos mit Lizenz' },
  dokumentation:  { seiten: 'ca. 100', mitte: 100, faktenmodus: 'streng', bilder: 'echte Fotos mit Lizenz' },
  malbuch:        { seiten: '24-30 (KDP-Minimum 24)', mitte: 27, faktenmodus: 'frei', bilder: 'Hauptinhalt; Malen nach Zahlen per Code' },
  raetsel:        { seiten: '40-70 (Vorschlag, noch nicht festgelegt)', mitte: 55, faktenmodus: 'frei', bilder: 'Raster und Lösungen per Code' },
  kinderbuch:     { seiten: '40-70 (Vorschlag, noch nicht festgelegt)', mitte: 55, faktenmodus: 'frei', bilder: 'viele Zeichnungen' },
  roman:          { seiten: '40-70 (Vorschlag, noch nicht festgelegt)', mitte: 55, faktenmodus: 'frei', bilder: 'kaum' },
  comic:          { seiten: '40-70 (Vorschlag), Innenteil Schwarz-Weiß', mitte: 55, faktenmodus: 'frei', bilder: 'Hauptinhalt; Beschriftung per Code' }
};

if (!/^\/neu\b/i.test(raw)) {
  return [{ json: { ok: false, antwort: 'Ich verstehe in dieser Version nur /neu.\n\n' + HILFE } }];
}
const rest = raw.replace(/^\/neu\s*/i, '');
const m = rest.match(/^([+-]18)(?!\d)\s*([\s\S]*)$/);
if (!m) {
  return [{ json: { ok: false, antwort: 'Die Altersstufe fehlt. Bitte +18 oder -18 angeben, ich nehme nichts an.\n\n' + HILFE } }];
}
let thema = m[2];
const alterszusatz = (thema.match(/\balter:(\S+)/i) || [])[1] || '';
thema = thema.replace(/\balter:\S+/ig, '');
let typ = ((thema.match(/\btyp:(\S+)/i) || [])[1] || '').toLowerCase();
thema = thema.replace(/\btyp:\S+/ig, '').replace(/\s+/g, ' ').trim();
if (!thema) {
  return [{ json: { ok: false, antwort: 'Das Thema fehlt.\n\n' + HILFE } }];
}
if (!PROFILE[typ]) {
  const t = thema.toLowerCase();
  if (/comic|manga|superhelden/.test(t)) typ = 'comic';
  else if (/malbuch|ausmal|malen nach zahlen|anmalbuch/.test(t)) typ = 'malbuch';
  else if (/sudoku|rätsel|raetsel|kreuzwort|suchsel|labyrinth/.test(t)) typ = 'raetsel';
  else if (/anleitung|bauplan|selber bauen|selbst bauen|diy|holz|handwerk|reparatur/.test(t)) typ = 'anleitung';
  else if (/geschichtsbuch|geschichte der|mittelalter|weltkrieg|antike|jahrhundert/.test(t)) typ = 'geschichtsbuch';
  else if (/dokumentation|chronik|atlas/.test(t)) typ = 'dokumentation';
  else if (/kinderbuch|bilderbuch|vorlesegeschichte|kindergeschichte/.test(t)) typ = 'kinderbuch';
  else if (/roman|fantasy|krimi|thriller|erzählung|novelle|kurzgeschichte/.test(t)) typ = 'roman';
  else typ = 'sachbuch';
}
const d = new Date();
const ymd = d.getFullYear() + String(d.getMonth() + 1).padStart(2, '0') + String(d.getDate()).padStart(2, '0');
const slug = ymd + '-' + thema.toLowerCase()
  .replace(/ä/g, 'ae').replace(/ö/g, 'oe').replace(/ü/g, 'ue').replace(/ß/g, 'ss')
  .normalize('NFKD').replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 50);

return [{ json: {
  ok: true,
  alter: m[1] === '+18' ? 'ab18' : 'unter18',
  alterszusatz, typ, thema, slug,
  ordner: String(cfg.ausgabe_basis),
  profil: PROFILE[typ]
} }];

const base = $('02 Prompt bauen').first().json;
const resp = $json;
const text = resp && resp.choices && resp.choices[0] && resp.choices[0].message && resp.choices[0].message.content;
if (!text) {
  const msg = (resp && resp.error && (resp.error.message || resp.error)) || (resp && resp.message) || JSON.stringify(resp || {}).slice(0, 300);
  return [{ json: { ok: false, antwort: 'Der Planer hat nicht geantwortet (OmniRoute): ' + msg + '\nPrüfe: Läuft OmniRoute? Stimmt der Schlüssel im Credential? Ist das Modell ' + base.requestBody.model + ' aktiv?' } }];
}
let t = String(text).trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
let v;
try { v = JSON.parse(t); }
catch (e) {
  const i = t.indexOf('{'), j = t.lastIndexOf('}');
  try { v = JSON.parse(t.slice(i, j + 1)); }
  catch (e2) { return [{ json: { ok: false, antwort: 'Die Antwort des Planers war kein lesbares JSON. Anfang: ' + t.slice(0, 200) } }]; }
}

const g = Array.isArray(v.gliederung) ? v.gliederung : [];
const L = [];
L.push('VORSCHAU (es wurde noch nichts geschrieben)');
L.push('Titel: ' + (v.arbeitstitel || '?') + (v.untertitel ? ' - ' + v.untertitel : ''));
L.push('Altersstufe: ' + (base.alter === 'ab18' ? '+18' : '-18') + (base.alterszusatz ? ' (' + base.alterszusatz + ')' : ''));
L.push('Buchart: ' + base.typ + ' | Faktenmodus: ' + base.profil.faktenmodus);
if (v.zielgruppe) L.push('Zielgruppe: ' + v.zielgruppe);
if (v.versprechen) L.push('Versprechen: ' + v.versprechen);
L.push('');
L.push('Gliederung (' + g.length + ' Kapitel):');
g.forEach((k, i) => L.push((i + 1) + '. ' + (k.kapitel || '') + (k.inhalt ? ' - ' + k.inhalt : '')));
L.push('');
L.push('Seitenziel: ' + base.profil.seiten);
const b = v.bilder || {};
L.push('Bilder: ' + (b.noetig === false ? 'nicht nötig' : 'nötig') + (b.art ? ' (' + b.art + ')' : '') + (b.hinweis ? ' - ' + b.hinweis : ''));
const tok = Math.round(base.profil.mitte * 300 * 1.6);
L.push('Verbrauch grob (Schätzung): Rohtext ca. ' + tok.toLocaleString('de-DE') + ' Tokens Ausgabe; mit Prüfung und Überarbeitung etwa das 3- bis 4-fache.');
if (Array.isArray(v.risiken) && v.risiken.length) { L.push(''); L.push('Risiken:'); v.risiken.forEach(r => L.push('- ' + r)); }
if (Array.isArray(v.rueckfragen) && v.rueckfragen.length) { L.push(''); L.push('Rückfragen an dich:'); v.rueckfragen.forEach(r => L.push('- ' + r)); }
L.push('');
L.push('Die Marktprüfung (Konkurrenz, Preise, Suchbegriffe) folgt in der nächsten Stufe.');
L.push('Hinweis: /ok, /aendern und /stopp werden im nächsten Baustein verdrahtet. Dieser Baustein erzeugt nur die Vorschau und den Speicherpunkt.');
const antwort = L.join('\n');

const state = {
  version: 1, slug: base.slug, speicherpunkt: 1, status: 'vorschau_wartet_auf_ok',
  auftrag: { thema: base.thema, typ: base.typ, alter: base.alter, alterszusatz: base.alterszusatz, faktenmodus: base.profil.faktenmodus, seiten: base.profil.seiten },
  erstellt: new Date().toISOString()
};
const mk = (name, obj) => ({
  json: { ok: true, pfad: base.ordner + '/' + base.slug + '__' + name, antwort },
  binary: { data: { data: Buffer.from(JSON.stringify(obj, null, 2), 'utf8').toString('base64'), mimeType: 'application/json', fileName: base.slug + '__' + name, fileExtension: 'json' } }
});
return [ mk('vorschau.json', { auftrag: state.auftrag, vorschau: v }), mk('state.json', state) ];
